	@Test
	void capsDictionaryMergeFanInByFileDescriptorsAndMemory() {
		PartitionValueDictionaryBuilder.MergeFanInPlan descriptorLimited = PartitionValueDictionaryBuilder
				.planMergeFanIn(20, 20L, 6, Long.MAX_VALUE, BulkCodec.NONE, 128L);

		assertThat(descriptorLimited.inputFanIn()).isEqualTo(5);
		assertThat(descriptorLimited.fileDescriptorCount()).isEqualTo(6);

		long budget = descriptorLimited.estimatedMemoryBytes() - 1L;
		PartitionValueDictionaryBuilder.MergeFanInPlan memoryLimited = PartitionValueDictionaryBuilder
				.planMergeFanIn(20, 20L, 6, budget, BulkCodec.NONE, 128L);

		assertThat(memoryLimited.inputFanIn()).isLessThan(descriptorLimited.inputFanIn());
		assertThat(memoryLimited.estimatedMemoryBytes()).isLessThanOrEqualTo(budget);
		assertThat(memoryLimited.requiresSerialMemoryFloor()).isFalse();
	}

	@Test
	void reportsTheIrreducibleTwoWayMergeMemoryFloor() {
		PartitionValueDictionaryBuilder.MergeFanInPlan plan = PartitionValueDictionaryBuilder
				.planMergeFanIn(20, 20L, 2, 16 * 1024L, BulkCodec.FAST, 128L);

		assertThat(plan.inputFanIn()).isEqualTo(2);
		assertThat(plan.fileDescriptorCount()).isEqualTo(3);
		assertThat(plan.requiresSerialMemoryFloor()).isTrue();
		assertThat(plan.minimumMemoryFloorBytes()).isGreaterThan(16 * 1024L);
		assertThat(plan.estimatedMemoryBytes()).isEqualTo(plan.minimumMemoryFloorBytes());
	}

