	private static List<String> dictionaryEntries(PartitionValueDictionary dictionary) throws IOException {
		List<String> entries = new ArrayList<>();
		dictionary.forEachEntry(entry -> entries.add(entry.partition() + ":" + HexFormat.of().formatHex(entry.key())
				+ ":" + entry.id() + ":" + entry.roles()));
		return entries;
	}

	private static void assertDictionarySemantics(PartitionValueDictionary dictionary, PredicateIdPlan predicatePlan,
			IRI predicate, IRI shared, LmdbStoreConfig config) throws IOException {
		List<PartitionValueDictionary.Entry> entries = new ArrayList<>();
		dictionary.forEachEntry(entries::add);
		PartitionValueDictionary.Entry sharedEntry = findEntry(entries, CanonicalTermCodec.encode(shared));
		int sharedRoles = CanonicalStatementStager.ROLE_SUBJECT | CanonicalStatementStager.ROLE_OBJECT
				| CanonicalStatementStager.ROLE_DEPENDENCY;
		assertThat(sharedEntry.roles() & sharedRoles).isEqualTo(sharedRoles);

		PartitionValueDictionary.Entry predicateEntry = findEntry(entries, CanonicalTermCodec.encode(predicate));
		assertThat(predicatePlan.idFor(predicateEntry.key())).isEqualTo(predicateEntry.id());
		assertThat(ValueIds.getValue(predicateEntry.id())).isEqualTo(1L);

		byte[] namespaceKey = CanonicalTermCodec.encodeNamespace(shared.getNamespace());
		PartitionValueDictionary.Entry namespaceEntry = findEntry(entries, namespaceKey);
		assertThat(namespaceEntry.roles()).isEqualTo(CanonicalStatementStager.ROLE_NAMESPACE);

		Value customLiteral = SimpleValueFactory.getInstance()
				.createLiteral("bulk-literal",
						SimpleValueFactory.getInstance().createIRI("urn:dictionary:datatype"));
		PartitionValueDictionary.Entry literalEntry = findEntry(entries, CanonicalTermCodec.encode(customLiteral));
		assertThat(ValueIds.getIdType(literalEntry.id())).isEqualTo(ValueIds.T_LITERAL);
		assertThat(ValueIds.getValue(literalEntry.id())).isPositive();
		assertThat(dictionary.inlineValues()).isPositive();
		assertThat(config.getInlineLiterals()).isTrue();
	}

	private static PartitionValueDictionary.Entry findEntry(List<PartitionValueDictionary.Entry> entries, byte[] key) {
		return entries.stream()
				.filter(entry -> java.util.Arrays.equals(entry.key(), key))
				.findFirst()
				.orElseThrow(() -> new AssertionError("missing dictionary key " + HexFormat.of().formatHex(key)));
	}

	private static IRI iriOutsidePartitions(SimpleValueFactory valueFactory, String role, int firstPartition,
			int secondPartition) {
		for (int candidate = 0;; candidate++) {
			IRI iri = valueFactory.createIRI("urn:oversized:" + role + ":" + candidate);
			int partition = (int) CanonicalTermCodec.routeHash64(CanonicalTermCodec.encode(iri)) & 3;
			if (partition != firstPartition && partition != secondPartition) {
				return iri;
			}
		}
	}
